import type { CatalogOperation, DeprecationEntry } from '../../packages/contracts/src/catalog/catalog';
import type { ScopeRegistry } from './scopes';

const GENERATED =
  '<!-- Generated by `pnpm catalog:generate` from the operation catalog. Do not edit by hand. -->';

export function renderScopesMd(reg: ScopeRegistry): string {
  const rows = reg.scopes.map(
    (s) =>
      `| \`${s.name}\` | ${s.principalClasses.join(', ')} | ${s.humanOnly ? 'yes' : 'no'} | ${s.owners.join(', ')} | ${s.sensitivity} | ${s.operations.length} |`,
  );
  return `${GENERATED}

# Scope registry

Machine-readable form: \`packages/contracts/src/catalog/scopes.json\`. The human registry of record is
the "Roles and scopes" section of [SHARED-CONTRACTS](../SHARED-CONTRACTS.md); CI fails when a scope the
catalog uses is not registered there, when a name is not \`noun.verb\` (a dotless camel-case name such
as \`receivablesRead\`, a wildcard or an empty name is a defect), or when this page is stale.

A scope alone never authorizes: the policy table also checks the principal kind, the live membership,
the location, and each domain command checks the resource (and, for portal principals, the S5
relationship). "Human only" means every operation using the scope admits only human principals, so a
grant of it to a service or agent principal can never be exercised (the forbidden-operation matrix,
docs/api/forbidden-matrix.md, proves the refusal). There is no grant API for staff scopes yet;
memberships are administered outside the API, and the default role-to-scope grants remain an open
human decision (A-D2). No default role grant is asserted here.

${reg.scopes.length} staff scopes.

| Scope | Principal kinds | Human only | Owners | Highest sensitivity | Operations |
|---|---|---|---|---|---|
${rows.join('\n')}

## Relationship scopes (S5)

Evaluated by the relationship policy for portal principals and relationship holders; never staff scopes
and never admitted by the staff policy table: ${reg.relationshipScopes.map((s) => `\`${s}\``).join(', ')}.
`;
}

export function renderCatalogMd(catalog: readonly CatalogOperation[]): string {
  const owners = ['F', 'A', 'S', 'C', 'B', 'E', 'I', 'M'] as const;
  const count = (f: (o: CatalogOperation) => boolean) => catalog.filter(f).length;
  const summary = owners.map(
    (w) =>
      `| ${w} | ${count((o) => o.owner === w)} | ${count((o) => o.owner === w && o.transports.includes('rest'))} | ${count((o) => o.owner === w && o.transports.includes('mcp'))} | ${count((o) => o.owner === w && o.transports.includes('portal'))} | ${count((o) => o.owner === w && o.transports.includes('bridge'))} | ${count((o) => o.owner === w && o.transports.includes('worker'))} |`,
  );
  const rows = catalog.map(
    (o) =>
      `| \`${o.operation}\` | ${o.owner} | ${o.kind} | ${o.authorization} | ${o.scope ? `\`${o.scope}\`` : '-'} | ${o.principals.join(', ')} | ${o.transports.join(', ') || '-'} | ${o.rest ? `${o.rest.method.toUpperCase()} \`${o.rest.path}\`` : '-'} | ${o.mcpTool ? `\`${o.mcpTool}\`` : '-'} | ${o.idempotency} | ${o.sensitivity} | ${o.status} |`,
  );
  return `${GENERATED}

# Operation catalog

Machine-readable form: \`packages/contracts/src/catalog/operations.json\`, generated from the policy
table, the route manifests, the MCP tool table and the worker's authorize calls. Authorization paths:
\`authorize\` (the staff policy table), \`portal\` (S5 relationship policy), \`device\` (live device row and
allowlist), \`pairing\` (one-time code), \`public\` (no tenant data) and \`capability\` (an additional
check inside another operation, never callable alone). \`kind\` and \`idempotency\` are derived from the
transport tables and are declarations, not independent proof.

${catalog.length} operations.

| Owner | Operations | REST | MCP | Portal | Bridge | Worker |
|---|---|---|---|---|---|---|
${summary.join('\n')}

| Operation | Owner | Kind | Authorization | Scope | Principals | Transports | REST | MCP tool | Idempotency | Sensitivity | Status |
|---|---|---|---|---|---|---|---|---|---|---|---|
${rows.join('\n')}
`;
}

export function renderSunsetMd(entries: readonly DeprecationEntry[]): string {
  const rows = entries.map(
    (d) =>
      `| \`${d.operation}\` | ${d.announced} | ${d.sunset} | ${d.replacedBy ? `\`${d.replacedBy}\`` : 'none (stated)'} | ${d.note} |`,
  );
  return `${GENERATED}

# Sunset register

Generated from \`packages/contracts/src/catalog/deprecations.json\`; the catalog marks each listed
operation \`deprecated\`. A deprecated operation still answers and still audits; REST responses carry
\`Deprecation\` and \`Sunset\` headers and MCP results a deprecation notice. The window length is an
open human decision (A-D1). See [deprecation.md](deprecation.md).

${entries.length === 0 ? 'No operation is deprecated.' : `| Operation | Announced | Sunset | Replaced by | Note |\n|---|---|---|---|---|\n${rows.join('\n')}`}
`;
}
